    size = 9
    row_sums = [12, 11, 12, 5, 7, 13, 12, 8, 2]
    col_sums = [7, 21, 11, 8, 3, 6, 11, 8, 7]

    # Grid of variables
    grid = [[model.NewIntVar(0, 1, f'x_{i}_{j}') for j in range(size)] for i in range(size)]

    # Row constraints: sum(j+1 * x_i_j) = row_sums[i]
    for i in range(size):
        model.Add(sum((j + 1) * grid[i][j] for j in range(size)) == row_sums[i])

    # Column constraints: sum(i+1 * x_i_j) = col_sums[j]
    for j in range(size):
        model.Add(sum((i + 1) * grid[i][j] for i in range(size)) == col_sums[j])

    solver = cp_model.CpSolver()
    status = solver.Solve(model)

