    col_current = [0]*n

    row_remain = [[0]*(n+1) for _ in range(n)]
    for i in range(n):
        for j in range(n-1, -1, -1):
            row_remain[i][j] = row_remain[i][j+1] + (j+1)

    col_remain = [[0]*(n+1) for _ in range(n)]
    for j in range(n):
        for i in range(n-1, -1, -1):
            col_remain[j][i] = col_remain[j][i+1] + (i+1)

    def backtrack(r, c):
        if r == n:
            return True

        next_r, next_c = (r, c + 1) if c < n - 1 else (r + 1, 0)

        # Try placing 1
        w_row = c + 1
        w_col = r + 1
        if row_current[r] + w_row <= row_targets[r] and col_current[c] + w_col <= col_targets[c]:
            grid[r][c] = 1
            row_current[r] += w_row
            col_current[c] += w_col

